entries.answer:
### .replit
```
run = "nix run"
entrypoint = "flake.nix"
modules = ["nix"]

[nix]
channel = "stable-24_05"

[agent]
expertMode = true
```

### replit.nix
```
{ pkgs }:
{
  deps = [ pkgs.ponyc ];
}
```

### flake.nix
```
{
  inputs = {
    nixpkgs.url = "nixpkgs";
    utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, utils }:
    utils.lib.eachDefaultSystem (system:
      let
        pkgs = nixpkgs.legacyPackages.${system};
        package = pkgs.callPackage ./default.nix { };
      in
      {
        packages.default = package;
        apps.default = {
          type = "app";
          program = "${package}/bin/pony";
        };
        devShells.default = pkgs.mkShell {
          buildInputs = [ pkgs.ponyc ];
        };
      }
    );
}
```

### default.nix
```
{ stdenv, ponyc }:
stdenv.mkDerivation {
  pname = "pony";
  version = "0.1.0";
  src = ./.;
  nativeBuildInputs = [ ponyc ];
  buildPhase = ''
    mkdir -p build
    ponyc --debug -o build ./pony
  '';
  installPhase = ''
    install -D build/pony $out/bin/pony
  '';
  meta = {
    mainProgram = "pony";
  };
}
```

### pony/main.pony
```
actor Main
  new create(env: Env) =>
    env.out.print("Hello from Pony")
```
